/**
 * Component: Logo grid
 * Author: @ariaw (https://tailwindflex.com/@ariaw)
 * Source: https://tailwindflex.com/@ariaw/logo-grid-3
 * Attribution: Créé par @ariaw sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function LogoGrid3() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en" dir="ltr">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Logo grid</title>

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    body {
      font-family: 'Inter', sans-serif;
    }

    .logo-img {
      filter: grayscale(100%) brightness(70%);
      transition: all 0.3s ease;
    }

    .logo-card {
      transition: all 0.3s ease;
      border: 1px solid transparent;
    }

    .logo-card:hover {
      border-color: #e5e5e5;
      transform: translateY(-5px);
    }

    .logo-card:hover .logo-img {
      filter: grayscale(0%) brightness(100%);
    }

    .floating-bg {
      background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.8) 0%, transparent 50%),
        radial-gradient(circle at 70% 70%, rgba(249, 249, 249, 0.6) 0%, transparent 50%);
    }
  </style>
</head>

<body class="bg-[#f9f9f9] min-h-screen flex items-center justify-center p-6 floating-bg">
  <div class="max-w-5xl w-full">
    <div class="text-center mb-20">
      <p class="text-gray-500 text-sm mb-4 font-medium uppercase tracking-wider">Partnerships</p>
      <h1 class="text-4xl md:text-5xl font-bold text-gray-900 mb-6">Trusted by forward-thinking brands</h1>
      <p class="text-gray-600 max-w-2xl mx-auto">
        We collaborate with companies that are shaping the future of their industries through innovation and excellence.
      </p>
    </div>

    <div class="grid grid-cols-2 md:grid-cols-4 gap-6 mb-16">
      <!-- Minimal Logo Cards -->
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/b/ba/Stripe_Logo%2C_revised_2016.svg" alt="Stripe" class="logo-img h-7">
      </div>
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/d/d5/Slack_icon_2019.svg" alt="Slack" class="logo-img h-7">
      </div>
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/1/1c/YouTube_Music_2024.svg" alt="Youtube Music" class="logo-img h-9">
      </div>
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/7/78/Soundcloud_logo.svg" alt="SoundCloud" class="logo-img h-7">
      </div>
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/HubSpot_Logo.svg/1920px-HubSpot_Logo.svg.png" alt="HubSpot" class="logo-img h-6">
      </div>
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/e/ec/Medium_logo_Monogram.svg" alt="Medium" class="logo-img h-7">
      </div>
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/b/bd/2024_Spotify_Logo.svg" alt="Spotify" class="logo-img h-9">
      </div>
      <div class="logo-card bg-white rounded-xl p-8 flex items-center justify-center">
        <img src="https://upload.wikimedia.org/wikipedia/commons/6/69/Airbnb_Logo_B%C3%A9lo.svg" alt="Airbnb" class="logo-img h-6">
      </div>
    </div>

    <div class="text-center">
      <p class="text-gray-500 text-sm mb-8">Interested in partnering with us?</p>
      <button class="bg-black text-white rounded-lg py-3 px-8 transition hover:bg-gray-800 font-medium">
                Start a Conversation
            </button>
    </div>
  </div>
</body>

</html>" }} />
  );
}
